import{_ as a,c as t,o as r,ag as i}from"./chunks/framework.DQvKz0xt.js";const m=JSON.parse('{"title":"运行时入门 (Getting Started with Runtimes) - Rive 运行时","description":"运行时 (Runtimes) Rive 运行时是将你在 Rive 编辑器中创建的动画集成到应用程序、网站或游戏中的桥梁。","frontmatter":{"title":"运行时入门 (Getting Started with Runtimes) - Rive 运行时","description":"运行时 (Runtimes) Rive 运行时是将你在 Rive 编辑器中创建的动画集成到应用程序、网站或游戏中的桥梁。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 运行时, 运行时入门"}]]},"headers":[],"relativePath":"runtimes/overview.md","filePath":"runtimes/overview.md","lastUpdated":1774838907000}'),n={name:"runtimes/overview.md"};function o(s,e,l,h,u,d){return r(),t("div",null,[...e[0]||(e[0]=[i('<p>运行时 (Runtimes)</p><h1 id="运行时入门-getting-started-with-runtimes" tabindex="-1">运行时入门 (Getting Started with Runtimes) <a class="header-anchor" href="#运行时入门-getting-started-with-runtimes" aria-label="Permalink to &quot;运行时入门 (Getting Started with Runtimes)&quot;">​</a></h1><p>Rive 运行时是将你在 Rive 编辑器中创建的动画集成到应用程序、网站或游戏中的桥梁。</p><h2 id="​-概览" tabindex="-1"><a href="#overview">​</a> 概览 <a class="header-anchor" href="#​-概览" aria-label="Permalink to &quot;[​](#overview) 概览&quot;">​</a></h2><p>Rive 为各种平台提供官方运行时库，让开发者可以轻松地在产品中嵌入和控制 Rive 动画。所有运行时都是开源的，你可以在 <a href="https://github.com/rive-app" target="_blank" rel="noreferrer">GitHub</a> 上找到源代码。</p><h2 id="​-选择运行时" tabindex="-1"><a href="#choosing-a-runtime">​</a> 选择运行时 <a class="header-anchor" href="#​-选择运行时" aria-label="Permalink to &quot;[​](#choosing-a-runtime) 选择运行时&quot;">​</a></h2><p>根据你的目标平台选择合适的运行时：</p><h3 id="web-应用" tabindex="-1">Web 应用 <a class="header-anchor" href="#web-应用" aria-label="Permalink to &quot;Web 应用&quot;">​</a></h3><ul><li><strong><a href="/docs/runtimes/web">Web (JS/TS)</a></strong> - 适用于原生 JavaScript 或任何前端框架</li><li><strong><a href="/docs/runtimes/react">React</a></strong> - 专为 React 应用优化的封装</li><li><strong><a href="/docs/runtimes/react-native">React Native</a></strong> - 用于跨平台移动应用</li></ul><h3 id="移动应用" tabindex="-1">移动应用 <a class="header-anchor" href="#移动应用" aria-label="Permalink to &quot;移动应用&quot;">​</a></h3><ul><li><strong><a href="/docs/runtimes/flutter">Flutter</a></strong> - 支持 iOS、Android、Web 和桌面</li><li><strong><a href="/docs/runtimes/apple">Apple (iOS/macOS)</a></strong> - 原生 Swift/SwiftUI 支持</li><li><strong><a href="/docs/runtimes/android">Android</a></strong> - 原生 Kotlin 支持</li></ul><h3 id="游戏引擎" tabindex="-1">游戏引擎 <a class="header-anchor" href="#游戏引擎" aria-label="Permalink to &quot;游戏引擎&quot;">​</a></h3><ul><li><strong><a href="/docs/games/unity">Unity</a></strong> - C# 运行时</li><li><strong><a href="/docs/games/unreal">Unreal Engine</a></strong> - C++ 运行时</li><li><strong><a href="/docs/games/defold">Defold</a></strong> - Lua 运行时</li></ul><h2 id="​-核心概念" tabindex="-1"><a href="#core-concepts">​</a> 核心概念 <a class="header-anchor" href="#​-核心概念" aria-label="Permalink to &quot;[​](#core-concepts) 核心概念&quot;">​</a></h2><p>无论使用哪个运行时，你都需要了解以下核心概念：</p><ul><li><strong><a href="/docs/runtimes/state-machines">状态机播放 (State Machine Playback)</a></strong> - 控制状态机的播放和输入</li><li><strong><a href="/docs/runtimes/data-binding">数据绑定 (Data Binding)</a></strong> - 在运行时动态更新文本、颜色、图像等</li><li><strong><a href="/docs/runtimes/loading-assets">加载资产 (Loading Assets)</a></strong> - 动态加载图像、字体和音频</li><li><strong><a href="/docs/runtimes/layout">布局 (Layout)</a></strong> - 控制画板的适应和对齐方式</li></ul><h2 id="​-功能支持" tabindex="-1"><a href="#feature-support">​</a> 功能支持 <a class="header-anchor" href="#​-功能支持" aria-label="Permalink to &quot;[​](#feature-support) 功能支持&quot;">​</a></h2><p>不同运行时对 Rive 功能的支持程度可能有所不同。请参阅 <a href="/docs/feature-support">功能支持页面</a> 了解详细的兼容性信息。</p><p>某些高级功能（如矢量羽化）仅在使用 <strong>Rive 渲染器</strong> 时可用。有关渲染器选择的指导，请参阅 <a href="/docs/runtimes/choose-a-renderer">选择渲染器</a> 页面。</p><h2 id="​-资源" tabindex="-1"><a href="#resources">​</a> 资源 <a class="header-anchor" href="#​-资源" aria-label="Permalink to &quot;[​](#resources) 资源&quot;">​</a></h2><ul><li><a href="https://github.com/rive-app" target="_blank" rel="noreferrer">GitHub 组织</a> - 所有开源运行时</li><li><a href="https://community.rive.app" target="_blank" rel="noreferrer">社区论坛</a> - 获取帮助和分享经验</li><li><a href="https://rive.app/community" target="_blank" rel="noreferrer">官方示例</a> - 浏览社区作品</li></ul><p><a href="/docs/runtimes/web">Web 运行时 (Web JS)</a><a href="/docs/runtimes/flutter">Flutter 运行时</a></p>',22)])])}const f=a(n,[["render",o]]);export{m as __pageData,f as default};
